// Describes failures by field path, keyword and expected type only; never the offending values.
function describeValidationErrors(toolName: string, errors: ErrorObject[]): string {
  const details = errors.map(error => {
    const path = error.instancePath || '(root)';
    const params = error.params as Record<string, unknown>;
    if (error.keyword === 'required') {
      return `${path}: required property "${String(params.missingProperty)}" is missing`;
    }
    if (error.keyword === 'type') {
      return `${path}: expected type ${String(params.type)}`;
    }
    if (error.keyword === 'additionalProperties') {
      return `${path}: unexpected property "${String(params.additionalProperty)}"`;
    }
    return `${path}: failed schema keyword "${error.keyword}"`;
  });
  return `Invalid input for tool "${toolName}": ${details.join('; ')}`;
}
"""
